from IQEngine.core.base import BaseObject
from IQEngine.interface import AbstractTax
from IQEngine.const import EntrustDirection, AssetType
from IQEngine.api.api_base import assure_asset
class StockTax(AbstractTax, BaseObject):
    def __init__(self, rate=None):
        if rate is None:
            self._rate = 0.001
            return None
        else:
            self._rate = float(rate)
            return None
    def set_tax(self, rate=0.001):
        self._rate = rate
    def calculate_tax(self, trade):
        fee = 0
        asset = assure_asset(trade.symbol)
        if trade.symbol[:2] not in ('11', '12') and asset.type not in (AssetType.ETF.value, AssetType.LOF.value) and trade.entrust_direction == EntrustDirection.SELL:
            cost_money = trade.price * trade.amount
            fee += cost_money * self._rate
        return fee
    @property
    def rate(self):
        return self._rate
